  // regenerates the lockfile pin from pubspec.yaml; `pub get
  // --enforce-lockfile` VERIFIES the pin matches and fails with the real
  // exit-65 error text on drift. A FA_FLUTTER_FAIL marker file forces the
  // failure for the NG2 tag-refusal test.
  File('${bin.path}/flutter').writeAsStringSync(r'''
#!/usr/bin/env bash
case " $* " in
  *" pub get"*) ;;
