  // #1265/#1268 enforce-lockfile shape) — the seed models it, and the bump
  // below carries it REFRESHED, exactly what the fixed auto_release.sh
  // ships and what the NG2 smoke in tag_release.sh verifies.
  Directory('$seed/flutter_app').createSync();
  File(
    '$seed/flutter_app/pubspec.yaml',
  ).writeAsStringSync('name: demo\nversion: 0.1.495+1\n');
  File('$seed/flutter_app/pubspec.lock').writeAsStringSync(
    '# Generated by pub (sandbox seed)\nversion: "0.1.495"\n',
  );
  _git(['add', '-A'], cwd: seed);
  _git(['commit', '-q', '-m', 'seed'], cwd: seed);
  _git(['tag', 'v0.1.495'], cwd: seed);
  _git(['push', '-q', 'origin', 'main', 'refs/tags/v0.1.495'], cwd: seed);

  // The bump — the commit the version tag must pin (gh-1192 AC3).
  File('$seed/pubspec.yaml').writeAsStringSync('name: demo\nversion: 0.1.496\n');
  File('$seed/CHANGELOG.md').writeAsStringSync(
      '# Changelog\n\n## 0.1.496\n\n- curated release note\n\n## Unreleased\n');
  File(
    '$seed/flutter_app/pubspec.yaml',
  ).writeAsStringSync('name: demo\nversion: 0.1.496+1\n');
