/// `curl` (serves the pub.dev package API from GH_STUB_DIR), and a `gh`
/// stub answering `run list`/`run view` from canned JSON while logging
/// every invocation.
class StubEnv {
  StubEnv(this.bin, this.realGit);
  final String bin; // prepend to PATH
  final String realGit; // exported as FA_REAL_GIT for the git shim
}

StubEnv _installStubs(String dir) {
  final bin = Directory('$dir/bin')..createSync(recursive: true);
  final realGit = _resolveRealGit(bin.path);

  File('${bin.path}/git').writeAsStringSync('''
#!/usr/bin/env bash
exec "\$FA_REAL_GIT" "\$@"
''');

  // gh-1299 flutter stub — cwd is always flutter_app/ (tag_release.sh does
  // `cd flutter_app && flutter pub get --enforce-lockfile`). `pub get`
  // regenerates the lockfile pin from pubspec.yaml; `pub get
  // --enforce-lockfile` VERIFIES the pin matches and fails with the real
  // exit-65 error text on drift. A FA_FLUTTER_FAIL marker file forces the
  // failure for the NG2 tag-refusal test.
  File('${bin.path}/flutter').writeAsStringSync(r'''
#!/usr/bin/env bash
case " $* " in
  *" pub get"*) ;;
  *) echo "flutter-stub: unexpected invocation: $*" >&2; exit 64 ;;
esac
if [ -f "${FA_FLUTTER_FAIL:-}" ]; then
  echo "Unable to satisfy \`pubspec.yaml\` using \`pubspec.lock\`. (stub)" >&2
  exit 65
fi
ver=$(sed -n 's/^version: \([0-9.]*\)+.*/\1/p' pubspec.yaml)
if printf '%s\n' "$*" | grep -q -- --enforce-lockfile; then
  pinned=$(sed -n 's/^version: "\(.*\)"$/\1/p' pubspec.lock 2>/dev/null | tail -1)
  if [ "$pinned" != "$ver" ]; then
    echo "Unable to satisfy \`pubspec.yaml\` using \`pubspec.lock\`." >&2
    echo "To update \`pubspec.lock\` run \`flutter pub get\` without" >&2
    echo "\`--enforce-lockfile\`." >&2
    echo "Failed to update packages." >&2
    exit 65
  fi
  exit 0
fi
printf '# Generated by pub (sandbox stub)\nversion: "%s"\n' "$ver" > pubspec.lock
''');

  // pub.dev package API: before the tag-run rerun lands, pub.dev serves the
  // OLD version; once $GH_STUB_DIR/rerun-done exists (planted by the gh
  // stub's `run rerun`), it serves the new one. A $GH_STUB_DIR/curl-fail
  // marker simulates an API outage; every invocation is logged to curl.log
  // so tests can assert the read happened (or never did).
